Here is an implementation of the quicksort algorithm in C#:
```
using System;

class QuickSort {
    static int partition(int arr[], int low, int high) {
        int pivot = arr[high];
        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (arr[j] < pivot) {
                i++;
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
        i--;
        for (int j = i + 1; j < high; j++) {
            if (arr[j] < pivot) {
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
        return i + 1;
    }

    static void quicksort(int arr[], int low, int high) {
        if (low < high) {
            int pivot = partition(arr, low, high);
            quicksort(arr, low, pivot - 1);
            quicksort(arr, pivot + 1, high);
        }
    }

    static void printArray(int arr[], int n) {
        for (int i = 0; i < n; i++) {
            Console.Write(arr[i] + " ");
        }
        Console.WriteLine();
    }

    static void main() {
        int arr[] = {17, 9, 13, 12, 11, 18, 19};
        int n = arr.Length;
        quicksort(arr, 0, n - 1);
        printArray(arr, n);
    }
}
```
This is a simple implementation of quicksort that uses the partition algorithm to choose a pivot element from the array, and recursively sorts the left and right subarrays until the entire array is sorted. The main method is used to test the quicksort algorithm by sorting the given array of integers.

