Here's the correct implementation of the quicksort algorithm in C++:
```scss
#include <iostream>
using namespace std;

void quicksort(int arr[], int low, int high) {
    if (low < high) {
        int partition(int arr[], int low, int high) {
            int pivot = arr[high];
            int i = low - 1;

            for (int j = low; j <= high - 1; j++) {
                if (arr[j] <= pivot) {
                    i++;
                    swap(arr[i], arr[j]);
