def delete_duplicates(head):
    current_node = head
    prev_node = None

    while current_node is not None:
        if current_node.value == prev_node.value:
            prev_node.next = current_node.next
            head = prev_node
            current_node = None
        else:
            prev_node = current_node
            current_node = current_node.next
    head = prev_node
    return head

