    def numDecodings(self, s):
        """
        :type s: str
        :rtype: int
        """
        if not s or s[0] == '0':
                return 0
        if len(s) == 1:
                return 1

        dp = [0]*len(s)
        dp[0] = 1

        if int(s[:2]) > 26:
                if s[1] != '0':
                        dp[1] = 1
                else:
                        dp[0] = 0
        else:
                if s[1] != '0':
                        dp[1] = 2
                else:
